using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.VTS.ReservacionesEstados;namespace GraphApi.Services.VTS.ReservacionesEstados{    public class ReservacionesEstadosService : IReservacionesEstadosService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public ReservacionesEstadosService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadReservacionesEstados>> GetReservacionesEstados(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM vts.ReservacionesEstados (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadReservacionesEstados>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetReservacionesEstadosDynamic(            int? reservacionEstadoID,            string? reservacionEstado,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "ReservacionEstadoID, ReservacionEstado, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM vts.ReservacionesEstados (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (reservacionEstadoID.HasValue)            {                vSql.Append(" AND ReservacionEstadoID = @ReservacionEstadoID");                vParameters.Add("ReservacionEstadoID",reservacionEstadoID);            }            if (!string.IsNullOrWhiteSpace(reservacionEstado))            {                vSql.Append(" AND ReservacionEstado LIKE @ReservacionEstado");                vParameters.Add("ReservacionEstado",$"%{reservacionEstado}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadReservacionesEstados> CreateReservacionesEstados(clCreateReservacionesEstados objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO vts.ReservacionesEstados                (ReservacionEstado, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@ReservacionEstado, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.ReservacionEstado,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT ReservacionEstadoID, ReservacionEstado, bEliminado                FROM vts.ReservacionesEstados (NOLOCK)                WHERE ReservacionEstadoID = @ReservacionEstadoID;";            var vReadParams = new { ReservacionEstadoID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadReservacionesEstados>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el ReservacionesEstado con ID {vNewId}.");            return vCreated;        }        public async Task<clReadReservacionesEstados?> UpdateReservacionesEstados(clUpdateReservacionesEstados objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("ReservacionEstadoID", objInput.ReservacionEstadoID);            if (objInput.ReservacionEstado is not null)            {                vSets.Add("ReservacionEstado = @ReservacionEstado");                vParameters.Add("ReservacionEstado", objInput.ReservacionEstado);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE vts.ReservacionesEstados                SET {vSetClause}                WHERE ReservacionEstadoID = @ReservacionEstadoID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT ReservacionEstadoID, ReservacionEstado, bEliminado                FROM vts.ReservacionesEstados (NOLOCK)                WHERE ReservacionEstadoID = @ReservacionEstadoID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadReservacionesEstados>(sSelect, new {  objInput.ReservacionEstadoID });        }        public async Task<bool> DeleteReservacionesEstados(int nReservacionesEstadosID)        {            const string sSql = @"                DELETE FROM vts.ReservacionesEstados                WHERE ReservacionEstadoID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nReservacionesEstadosID });            return vAffected > 0;        }    }}